"""Coverage states stay independent: source/implementation/live/fallback."""
from pathlib import Path
import json,re
HERE=Path(__file__).resolve().parent;PORT=HERE.parents[1]
def main():
 cars=json.loads((PORT/'docs/vehicle-continuity2/fleet-car/race-profiles.json').read_text())['profiles'];damage=json.loads((HERE/'car/contracts.json').read_text())['profiles'];wheels=json.loads((HERE/'wheels/manifest.json').read_text())['fleet'];lamps=json.loads((HERE/'lamps/source-registry.json').read_text())['families'];frontend={m[0]:{'ps2_family':m[1],'file':m[2],'sha256':m[3]}for m in re.findall(r'\{"([^"\n]+)","([^"\n]+)","([^"\n]+\.ps2model)","([a-f0-9]{64})"',(PORT/'renderer/frontend_fleet_registry.hpp').read_text())}
 rows=[]
 for car in cars:
  f=car['family'];d=next(d for d in damage if d['family']==f);w=next(w for w in wheels if w['family']==f);lamp=next(l for l in lamps if l['family']==f);live=f in ('Xtrail','KiaSportage');wheel_none=f=='Ufo';off=lamp['off_status']=='SOURCE_ADMITTED';damage_enabled=live or d['eligible']
  row={'family':f,'ps2_family':car['ps2_family'],'COMPLETE':{'source_ready':f in frontend,'implemented':f in frontend,'asset':frontend.get(f),'runtime_status':'PREVIOUS_FLEET_USER_TESTS_PARTIAL_PER_FAMILY_LEDGER' if f!='Xtrail' else 'USER_RUNTIME_CONFIRMED'},'CAR':{'source_ready':True,'asset':car['filename'],'sha256':car['sha256'],'implemented':True,'native_owner':'CURRENT_FRAME_WHOLE_OPAQUE_ALPHA_SOURCE_COHORT_REQUIRED','healthy_runtime':'USER_RUNTIME_CONFIRMED' if live else 'IMPLEMENTED_RUNTIME_PENDING','damaged_implemented':damage_enabled,'damaged_runtime':'USER_RUNTIME_CONFIRMED' if live else 'IMPLEMENTED_RUNTIME_PENDING' if d['eligible'] else 'EXACT_WHOLE_BODY_STOCK_FALLBACK','damage_unresolved_vertices':len(d['unresolved_vertices']),'source_records':len(car['pc_sources'])},'wheels':{'source_ready':not wheel_none,'implemented':not wheel_none,'policy':'NO_WHEELS_BY_DESIGN' if wheel_none else 'ACCEPTED_SPECIALIZED_NATIVE_OWNERS' if live else 'COMPLETE_PER_CURRENT_OWNER_COHORT; NO_ASSUMED_OWNER_COUNT','source_records':w.get('native_source_count',0),'native_owner_count':None if not live else 4,'runtime':'NOT_APPLICABLE' if wheel_none else 'USER_RUNTIME_CONFIRMED' if live else 'IMPLEMENTED_RUNTIME_PENDING','damage_policy':'UNCHANGED_NATIVE_WHEEL_SOURCES_ONLY; PRIVATE_WHEEL_TREES_STOCK'},'reflection_mode4':{'implemented':True,'runtime':'USER_RUNTIME_CONFIRMED' if live else 'PRIVATE_CAR_MATERIAL_TRANSACTIONS_RUNTIME_PENDING','pixel_parity':False},'lamps':{'OFF':{'source_ready':off,'implemented':off,'runtime':'PREVIOUS_ACCEPTED_PATH' if live else 'OWNER_BOUND_RUNTIME_PENDING' if off else 'STOCK_EXACT_SOURCE_BLOCKER'},'ON_CORE':{'source_ready':True,'implemented':True,'runtime':'USER_RUNTIME_CONFIRMED' if f=='KiaSportage' else 'OWNER_BOUND_RUNTIME_PENDING','original_gxi':'fd4c121f962ef4e9ee7491666c71b65db008d6ca276d9188881c0b35c7846131','secondary_gs_parity':'NOT_CLAIMED'},'ADDITIVE_GLOW':{'source_ready':True,'implemented':True,'runtime':'USER_RUNTIME_CONFIRMED' if f=='KiaSportage' else 'NEW_OWNER_BOUND_PATH_RUNTIME_PENDING'},'damaged':'USER_RUNTIME_CONFIRMED' if f=='KiaSportage' else 'IMPLEMENTED_HEALTHY_REFERENCE_AND_CURRENT_NATIVE_CLONE_REQUIRED'},'Reset_MSAA_performance':{'runtime':'USER_RUNTIME_CONFIRMED_MSAA4_RESET' if live else 'AUTOMATED_CONTRACTS_PASS_LIVE_PENDING','measurements_fps':None}}
  rows.append(row)
 data={'schema':1,'phase':'PS2-VEHICLE-FLEET-PORT3','ufo_has_wheels':False,'ps2_FORESTER_is_NOT_pc_Forester':True,'preserved_controls':['Xtrail','KiaSportage'],'new_fleet_runtime_status':'PENDING_USER_BATCH','vehicles':rows};(HERE/'coverage.json').write_text(json.dumps(data,indent=2)+'\n')
 lines=['# Fleet coverage','', 'Implemented means fail-closed runtime admission exists, not that a game run was observed. UFO has no wheels. PC Forester maps to WOOLDAND; PS2 FORESTER stays separate.','', '| Vehicle | CAR healthy | CAR damaged | PS2 wheels | OFF | ON/glow |','|---|---|---|---|---|---|']
 for r in rows:lines.append('| '+r['family']+' | '+r['CAR']['healthy_runtime']+' | '+r['CAR']['damaged_runtime']+' | '+r['wheels']['runtime']+' | '+r['lamps']['OFF']['runtime']+' | '+r['lamps']['ON_CORE']['runtime']+' |')
 (HERE/'coverage.md').write_text('\n'.join(lines)+'\n');print({'cars':len(rows),'wheeled':sum(r['wheels']['implemented'] for r in rows),'damage_enabled':sum(r['CAR']['damaged_implemented'] for r in rows),'off':sum(r['lamps']['OFF']['implemented'] for r in rows),'on_glow':25})
if __name__=='__main__':main()
